문 12. 다음 C 프로그램의 실행 결과로 옳은 것은?
#include <stdio.h>
void swap(int i, int *j) {
int tmp;
tmp = i;
i = *j;
*j = tmp;
}
void main() {
int i, j;
i = 10;
j = 9;
swap(i, &j);
printf("%d\n", i - 1);
}

