문 20. 다음 Java 프로그램의 실행 결과로 옳은 것은?
class TestExcep {
static int a, b;
public static void div() {
try {
System.out.println("a를 b로 나눈 몫 = " + (a / b));
} catch(Exception e) {
System.out.println("Exception 처리 루틴2 : ");
} finally {
System.out.println("div()의 finally 블록 수행");
}
}
public static void main(String args[]) {
try {
a = 1;
b = 1;
div();
} catch(Exception e) {
System.out.println("Exception 처리 루틴1 : ");
} finally {
System.out.println("main()의 finally 블록 수행");
}
}
}
